INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das Dependency Inversion Principle nur für Objektorientierung?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in anderen Paradigmen nützlich"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Dependency Inversion Principle?', 3, '[{"text": "Abhängigkeit von Abstraktionen", "correct": true, "because": "Reduziert Kopplung"}, {"text": "Code kürzen", "correct": false, "because": "Nicht primär"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Performance-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken unterstützen das Dependency Inversion Principle?', 5, '[{"text": "Dependency Injection", "correct": true, "because": "Abstraktionen übergeben"}, {"text": "Interfaces", "correct": true, "because": "Definieren Abhängigkeiten"}, {"text": "Globale Variablen", "correct": false, "because": "Erhöht Kopplung"}, {"text": "Direkte Instanziierung", "correct": false, "because": "Widerspricht DIP"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DIP reduziert Kopplung. b) Es eliminiert alle Abhängigkeiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abhängigkeiten bleiben, aber abstrakt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Dependency Inversion Principle?', 4, '[{"text": "Abstraktionen", "correct": false, "because": "Kern des Prinzips"}, {"text": "Lose Kopplung", "correct": false, "because": "Ziel von DIP"}, {"text": "UI-Design", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DIP mehr Planung erfordert?', 2, '[{"text": "Ja", "correct": true, "because": "Abstraktionen müssen entworfen werden"}, {"text": "Nein", "correct": false, "because": "Planung essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel folgt dem Dependency Inversion Principle?', 3, '[{"text": "Klasse nutzt Interface statt konkrete Klasse", "correct": true, "because": "Abhängigkeit abstrakt"}, {"text": "Klasse instanziiert direkt", "correct": false, "because": "Feste Kopplung"}, {"text": "Klasse ohne Abhängigkeiten", "correct": false, "because": "Nicht DIP-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Dependency Inversion Principle?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Leichter Austausch"}, {"text": "Testbarkeit", "correct": true, "because": "Mocks einfacher"}, {"text": "Schnellere Kompilierung", "correct": false, "because": "Kein Build-Fokus"}, {"text": "Weniger Zeilen", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DIP erleichtert Erweiterung. b) Es macht Code immer einfacher. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Komplexität kann steigen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Dependency Inversion Principle?', 4, '[{"text": "Abstrakte Schnittstellen", "correct": false, "because": "Grundlage DIP"}, {"text": "Dependency Injection", "correct": false, "because": "Häufig genutzt"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DIP ohne Interfaces möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Abstrakte Klassen reichen"}, {"text": "Nein", "correct": false, "because": "Interfaces üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften fördert das Dependency Inversion Principle?', 4, '[{"text": "Lose Kopplung", "correct": true, "because": "Abhängigkeit abstrakt"}, {"text": "Wartbarkeit", "correct": true, "because": "Änderungen einfacher"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Performance-Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DIP nur für Tests ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Design verbessert"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Dependency Inversion Principle?', 3, '[{"text": "Abstraktionen", "correct": true, "because": "Vermeidet feste Bindungen"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Design zählt"}, {"text": "Viele Abhängigkeiten", "correct": false, "because": "Widerspricht DIP"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DIP fördert Mocking. b) Es ersetzt konkrete Klassen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Klassen bleiben, aber abstrakt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat das Dependency Inversion Principle?', 5, '[{"text": "Höherer Designaufwand", "correct": true, "because": "Abstraktion braucht Planung"}, {"text": "Mehr Schnittstellen", "correct": true, "because": "Abstraktionen steigen"}, {"text": "Langsamere Ausführung", "correct": false, "because": "Kein Performance-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Dependency Inversion Principle unwichtig?', 3, '[{"text": "Abstraktion", "correct": false, "because": "Kernprinzip"}, {"text": "Lose Kopplung", "correct": false, "because": "Ziel von DIP"}, {"text": "Farbanimationen", "correct": true, "because": "Kein Code-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht DIP die Komplexität?', 3, '[{"text": "Ja", "correct": true, "because": "Abstraktion kann komplexer sein"}, {"text": "Nein", "correct": false, "because": "Langfristig einfacher"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DIP Refactoring erleichtert?', 2, '[{"text": "Ja", "correct": true, "because": "Lose Kopplung hilft"}, {"text": "Nein", "correct": false, "because": "Änderungen simpler"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug unterstützt das Dependency Inversion Principle?', 4, '[{"text": "IoC-Container", "correct": true, "because": "Managed Injection"}, {"text": "Compiler", "correct": false, "because": "Nur Übersetzung"}, {"text": "Debugger", "correct": false, "because": "Fehlerfokussiert"}]');
